namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly StudentsController _controller;

        public StudentsControllerTests()
        {
            _context = TestDbContext.Create();
            _controller = new StudentsController(_context);
            _controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(), new Mock<ITempDataProvider>().Object);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private Student CreateStudent(string lastName = "Smith", string firstName = "John", DateTime? enrollmentDate = null)
        {
            var student = new Student
            {
                LastName = lastName,
                FirstMidName = firstName,
                EnrollmentDate = enrollmentDate ?? new DateTime(2023, 9, 1)
            };
            _context.Students.Add(student);
            _context.SaveChanges();
            return student;
        }

        [Fact]
        public void Index_NoParams_ReturnsViewWithStudentsOrderedByLastName()
        {
            CreateStudent("Zeta", "Alice");
            CreateStudent("Alpha", "Bob");

            var result = _controller.Index(null, null, null, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal("Alpha", model[0].LastName);
            Assert.Equal("Zeta", model[1].LastName);
        }

        [Theory]
        [InlineData("name_desc", "Zeta")]
        [InlineData("", "Alpha")]
        [InlineData(null, "Alpha")]
        public void Index_SortOrder_SortsCorrectly(string sortOrder, string expectedFirstLastName)
        {
            CreateStudent("Zeta", "Alice", new DateTime(2023, 1, 1));
            CreateStudent("Alpha", "Bob", new DateTime(2024, 1, 1));

            var result = _controller.Index(sortOrder, null, null, null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal(expectedFirstLastName, model[0].LastName);
        }

        [Fact]
        public void Index_DateSort_OrdersByEnrollmentDate()
        {
            CreateStudent("B", "X", new DateTime(2024, 1, 1));
            CreateStudent("A", "Y", new DateTime(2020, 1, 1));

            var result = _controller.Index("Date", null, null, null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal("A", model[0].LastName); // earlier date first
        }

        [Fact]
        public void Index_DateDescSort_OrdersByEnrollmentDateDescending()
        {
            CreateStudent("B", "X", new DateTime(2024, 1, 1));
            CreateStudent("A", "Y", new DateTime(2020, 1, 1));

            var result = _controller.Index("date_desc", null, null, null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal("B", model[0].LastName); // later date first
        }

        [Fact]
        public void Index_SearchString_FiltersStudentsByLastName()
        {
            CreateStudent("Smith", "John");
            CreateStudent("Johnson", "Jane");

            var result = _controller.Index(null, null, "Smith", null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Single(model);
            Assert.Equal("Smith", model[0].LastName);
        }

        [Fact]
        public void Index_SearchString_FiltersStudentsByFirstName()
        {
            CreateStudent("Smith", "John");
            CreateStudent("Johnson", "Jane");

            var result = _controller.Index(null, null, "Jane", null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Single(model);
            Assert.Equal("Johnson", model[0].LastName);
        }

        [Fact]
        public void Index_NewSearchString_ResetsPageTo1()
        {
            // When searchString is provided, page should reset to 1
            for (int i = 0; i < 15; i++)
                CreateStudent($"Student{i}", "First");

            var result = _controller.Index(null, null, "Student1", 3) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal(1, model.PageIndex);
        }

        [Fact]
        public void Index_NullSearchString_UsesCurrentFilter()
        {
            CreateStudent("Smith", "John");
            CreateStudent("Johnson", "Jane");

            var result = _controller.Index(null, "Smith", null, null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Single(model);
        }

        [Fact]
        public void Details_ValidId_ReturnsStudentWithEnrollments()
        {
            var student = CreateStudent();
            var course = new Course { CourseID = 100, Title = "Math", Credits = 3, DepartmentID = 0 };
            _context.Courses.Add(course);
            _context.Enrollments.Add(new Enrollment { StudentID = student.ID, CourseID = 100, Grade = Grade.A });
            _context.SaveChanges();

            var result = _controller.Details(student.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal(student.ID, model.ID);
            Assert.Single(model.Enrollments);
        }

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Create_Get_ReturnsViewWithStudentAndTodayDate()
        {
            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal(DateTime.Today, model.EnrollmentDate);
        }

        [Fact]
        public void Create_Post_ValidStudent_RedirectsToIndex()
        {
            var student = new Student
            {
                LastName = "Doe",
                FirstMidName = "Jane",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            var result = _controller.Create(student) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Single(_context.Students);
        }

        [Fact]
        public void Create_Post_InvalidEnrollmentDate_ReturnsViewWithError()
        {
            var student = new Student
            {
                LastName = "Doe",
                FirstMidName = "Jane",
                EnrollmentDate = DateTime.MinValue
            };

            var result = _controller.Create(student) as ViewResult;

            Assert.NotNull(result);
            Assert.False(_controller.ModelState.IsValid);
            Assert.Empty(_context.Students);
        }

        [Fact]
        public void Create_Post_EnrollmentDateOutOfRange_ReturnsViewWithError()
        {
            var student = new Student
            {
                LastName = "Doe",
                FirstMidName = "Jane",
                EnrollmentDate = new DateTime(1500, 1, 1)
            };

            var result = _controller.Create(student) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsViewWithStudent()
        {
            var student = CreateStudent();

            var result = _controller.Edit(student.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal(student.ID, model.ID);
        }

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_Get_NonExistentId_ReturnsNotFound()
        {
            var result = _controller.Edit(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_Post_ValidStudent_RedirectsToIndex()
        {
            var student = CreateStudent();
            student.LastName = "UpdatedName";

            var result = _controller.Edit(student) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
        }

        [Fact]
        public void Edit_Post_InvalidEnrollmentDate_ReturnsView()
        {
            var student = CreateStudent();
            student.EnrollmentDate = DateTime.MinValue;

            var result = _controller.Edit(student) as ViewResult;

            Assert.NotNull(result);
            Assert.False(_controller.ModelState.IsValid);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsView()
        {
            var student = CreateStudent();

            var result = _controller.Delete(student.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal(student.ID, model.ID);
        }

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_Get_NonExistentId_ReturnsNotFound()
        {
            var result = _controller.Delete(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void DeleteConfirmed_RemovesStudentAndRedirects()
        {
            var student = CreateStudent();

            var result = _controller.DeleteConfirmed(student.ID) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Empty(_context.Students);
        }
    }
}
