        public CoursesControllerTests()
        {
            _context = TestDbContext.Create();
            _envMock = new Mock<IWebHostEnvironment>();
            _envMock.Setup(e => e.WebRootPath).Returns(Path.GetTempPath());
            _envMock.Setup(e => e.ContentRootPath).Returns(Path.GetTempPath());
            _loggerMock = new Mock<ILogger<CoursesController>>();
            _controller = new CoursesController(_context, _envMock.Object, _loggerMock.Object);
            _controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(), new Mock<ITempDataProvider>().Object);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private Department CreateDepartment(string name = "Engineering")
        {
            var dept = new Department { Name = name, Budget = 100000, StartDate = new DateTime(2020, 1, 1) };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            return dept;
        }

        private Course CreateCourse(int id = 1001, string title = "Calculus", int credits = 3, Department dept = null)
        {
            dept ??= CreateDepartment();
            var course = new Course { CourseID = id, Title = title, Credits = credits, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();
            return course;
        }

        [Fact]
        public void Index_ReturnsCourseListWithDepartment()
        {
            var dept = CreateDepartment("Math");
            CreateCourse(101, "Algebra", 3, dept);

            var result = _controller.Index() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<IEnumerable<Course>>(result.Model);
            var courseList = model.ToList();
            Assert.Single(courseList);
            Assert.Equal("Algebra", courseList[0].Title);
            Assert.Equal("Math", courseList[0].Department.Name);
        }

        [Fact]
        public void Details_ValidId_ReturnsCourseWithDepartment()
        {
            var dept = CreateDepartment("Science");
            var course = CreateCourse(201, "Physics", 4, dept);

            var result = _controller.Details(course.CourseID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Course>(result.Model);
            Assert.Equal("Physics", model.Title);
            Assert.Equal("Science", model.Department.Name);
        }

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Create_Get_ReturnsViewWithDepartmentSelectList()
        {
            CreateDepartment("CS");

            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            Assert.NotNull(_controller.ViewBag.DepartmentID);
        }

        [Fact]
        public void Create_Post_ValidCourse_RedirectsToIndex()
        {
            var dept = CreateDepartment();
            var course = new Course { CourseID = 300, Title = "New Course", Credits = 3, DepartmentID = dept.DepartmentID };

            var result = _controller.Create(course, null) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.NotNull(_context.Courses.Find(300));
        }

        [Fact]
        public void Create_Post_InvalidModel_ReturnsView()
        {
            _controller.ModelState.AddModelError("Title", "Required");
            var course = new Course { CourseID = 400, Credits = 3 };

            var result = _controller.Create(course, null) as ViewResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void Create_Post_WithInvalidFileExtension_ReturnsModelError()
        {
            var dept = CreateDepartment();
            var course = new Course { CourseID = 500, Title = "Course", Credits = 3, DepartmentID = dept.DepartmentID };
            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("file.exe");
            fileMock.Setup(f => f.Length).Returns(1024);

            var result = _controller.Create(course, fileMock.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Create_Post_WithOversizedFile_ReturnsModelError()
        {
            var dept = CreateDepartment();
            var course = new Course { CourseID = 501, Title = "Course", Credits = 3, DepartmentID = dept.DepartmentID };
            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("file.jpg");
            fileMock.Setup(f => f.Length).Returns(10 * 1024 * 1024); // 10MB

            var result = _controller.Create(course, fileMock.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Create_Post_WithValidImage_SavesFileAndRedirects()
        {
            var dept = CreateDepartment();
            var course = new Course { CourseID = 502, Title = "Course", Credits = 3, DepartmentID = dept.DepartmentID };
            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("image.png");
            fileMock.Setup(f => f.Length).Returns(1024);
            fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            var result = _controller.Create(course, fileMock.Object) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            var saved = _context.Courses.Find(502);
            Assert.NotNull(saved.TeachingMaterialImagePath);
            Assert.Contains("/Uploads/TeachingMaterials/", saved.TeachingMaterialImagePath);
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsView()
        {
            var course = CreateCourse();

            var result = _controller.Edit(course.CourseID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Course>(result.Model);
            Assert.Equal(course.CourseID, model.CourseID);
        }

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_Get_NonExistentId_ReturnsNotFound()
        {
            var result = _controller.Edit(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_Post_ValidCourse_RedirectsToIndex()
        {
            var course = CreateCourse();
            course.Title = "Updated Title";

            var result = _controller.Edit(course, null) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsView()
        {
            var course = CreateCourse();

            var result = _controller.Delete(course.CourseID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Course>(result.Model);
            Assert.Equal(course.CourseID, model.CourseID);
        }

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void DeleteConfirmed_RemovesCourseAndRedirects()
        {
            var course = CreateCourse(600, "ToDelete");

            var result = _controller.DeleteConfirmed(course.CourseID) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Null(_context.Courses.Find(600));
        }
    }
