using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class InstructorsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly InstructorsController _controller;

        public InstructorsControllerTests()
        {
            _context = TestDbContext.Create();
            _controller = new InstructorsController(_context);
            _controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(), new Mock<ITempDataProvider>().Object);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private Instructor CreateInstructor(string lastName = "Fakhouri", string firstName = "Fadi", List<Course> courses = null)
        {
            var instructor = new Instructor
            {
                LastName = lastName,
                FirstMidName = firstName,
                HireDate = new DateTime(2020, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            if (courses != null)
            {
                foreach (var course in courses)
                {
                    _context.CourseAssignments.Add(new CourseAssignment
                    {
                        InstructorID = instructor.ID,
                        CourseID = course.CourseID
                    });
                }
                _context.SaveChanges();
                // Reload to get navigation properties
                _context.Entry(instructor).Collection(i => i.CourseAssignments).Load();
            }

            return instructor;
        }

        private Course CreateCourse(int id, string title = "Course")
        {
