using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class InstructorsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly InstructorsController _controller;

        public InstructorsControllerTests()
        {
            _context = TestDbContext.Create();
            _controller = new InstructorsController(_context);
            _controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(), new Mock<ITempDataProvider>().Object);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private Instructor CreateInstructor(string lastName = "Fakhouri", string firstName = "Fadi", List<Course> courses = null)
        {
            var instructor = new Instructor
            {
                LastName = lastName,
                FirstMidName = firstName,
                HireDate = new DateTime(2020, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            if (courses != null)
            {
                foreach (var course in courses)
                {
                    _context.CourseAssignments.Add(new CourseAssignment
                    {
                        InstructorID = instructor.ID,
                        CourseID = course.CourseID
                    });
                }
                _context.SaveChanges();
                // Reload to get navigation properties
                _context.Entry(instructor).Collection(i => i.CourseAssignments).Load();
            }

            return instructor;
        }

        private Course CreateCourse(int id, string title = "Course")
        {
            var dept = new Department { Name = "Dept", Budget = 10000, StartDate = DateTime.Now };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            var course = new Course { CourseID = id, Title = title, Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();
            return course;
        }

        [Fact]
        public void Index_NoParams_ReturnsAllInstructorsOrdered()
        {
            CreateInstructor("Zheng", "Roger");
            CreateInstructor("Adams", "Kim");

            var result = _controller.Index(null, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<InstructorIndexData>(result.Model);
            var instructors = model.Instructors.ToList();
            Assert.Equal(2, instructors.Count);
            Assert.Equal("Adams", instructors[0].LastName);
            Assert.Equal("Zheng", instructors[1].LastName);
        }

        [Fact]
        public void Index_WithInstructorId_PopulatesCourses()
        {
            var course = CreateCourse(101, "Algebra");
            var instructor = CreateInstructor("Prof", "A", new List<Course> { course });

            var result = _controller.Index(instructor.ID, null) as ViewResult;

            var model = Assert.IsType<InstructorIndexData>(result.Model);
            Assert.NotNull(model.Courses);
            Assert.Single(model.Courses);
            Assert.Equal("Algebra", model.Courses.First().Title);
        }

        [Fact]
        public void Details_ValidId_ReturnsInstructor()
        {
            var instructor = CreateInstructor("TestProf", "A");

            var result = _controller.Details(instructor.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.Equal("TestProf", model.LastName);
        }

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_NonExistentId_ReturnsNotFound()
        {
            var result = _controller.Details(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Create_Get_ReturnsViewWithCourseData()
        {
            CreateCourse(101, "Math");

            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.NotNull(model.CourseAssignments);
            Assert.NotNull(_controller.ViewBag.Courses);
        }

        [Fact]
        public void Create_Post_ValidInstructor_RedirectsToIndex()
        {
            var instructor = new Instructor
            {
                LastName = "NewProf",
                FirstMidName = "Bob",
                HireDate = new DateTime(2023, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = _controller.Create(instructor, null) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Equal(1, _context.Instructors.Count(i => i.LastName == "NewProf"));
        }

        [Fact]
        public void Create_Post_WithSelectedCourses_AssignsCourses()
        {
            var course = CreateCourse(201);
            var instructor = new Instructor
            {
                LastName = "CoursedProf",
                FirstMidName = "Bob",
                HireDate = new DateTime(2023, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = _controller.Create(instructor, new[] { "201" }) as RedirectToActionResult;

            Assert.NotNull(result);
            var saved = _context.Instructors.First(i => i.LastName == "CoursedProf");
            _context.Entry(saved).Collection(i => i.CourseAssignments).Load();
            Assert.Single(saved.CourseAssignments);
        }

        [Fact]
