using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class HomeControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly HomeController _controller;

        public HomeControllerTests()
        {
            _context = TestDbContext.Create();
            _controller = new HomeController(_context);
            _controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(), new Mock<ITempDataProvider>().Object);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Index_ReturnsView()
        {
            var result = _controller.Index() as ViewResult;
            Assert.NotNull(result);
        }

        [Fact]
        public void About_ReturnsEnrollmentDateGroups()
        {
            _context.Students.Add(new Student
            {
                LastName = "A",
                FirstMidName = "B",
                EnrollmentDate = new DateTime(2023, 9, 1)
            });
            _context.Students.Add(new Student
            {
                LastName = "C",
                FirstMidName = "D",
                EnrollmentDate = new DateTime(2023, 9, 1)
            });
            _context.Students.Add(new Student
            {
                LastName = "E",
                FirstMidName = "F",
                EnrollmentDate = new DateTime(2024, 1, 15)
            });
            _context.SaveChanges();

            var result = _controller.About() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<IEnumerable<EnrollmentDateGroup>>(result.Model);
            var groups = model.ToList();
            Assert.Equal(2, groups.Count);
            Assert.Contains(groups, g => g.StudentCount == 2);
            Assert.Contains(groups, g => g.StudentCount == 1);
        }

        [Fact]
        public void Contact_SetsViewBagMessage()
        {
            var result = _controller.Contact() as ViewResult;

            Assert.NotNull(result);
            Assert.Equal("Your contact page.", _controller.ViewBag.Message);
        }

        [Fact]
        public void Error_ReturnsView()
        {
            var result = _controller.Error() as ViewResult;
            Assert.NotNull(result);
        }

        [Fact]
        public void Unauthorized_SetsMessageAndReturnsView()
        {
            var result = _controller.Unauthorized() as ViewResult;

            Assert.NotNull(result);
            Assert.Contains("permission", (string)_controller.ViewBag.Message);
        }
    }
}

