using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class SchoolContextTests
    {
        [Fact]
        public void CanAddAndRetrieveStudent()
        {
            using var context = TestDbContext.Create();
            var student = new Student
            {
                LastName = "Doe",
                FirstMidName = "John",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            context.Students.Add(student);
            context.SaveChanges();

            var retrieved = context.Students.First();
            Assert.Equal("Doe", retrieved.LastName);
            Assert.Equal("John", retrieved.FirstMidName);
        }

        [Fact]
        public void CanAddAndRetrieveCourse()
        {
            using var context = TestDbContext.Create();
            var dept = new Department { Name = "Math", Budget = 50000, StartDate = DateTime.Now };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course { CourseID = 101, Title = "Algebra", Credits = 3, DepartmentID = dept.DepartmentID };
            context.Courses.Add(course);
            context.SaveChanges();

            var retrieved = context.Courses.Include(c => c.Department).First();
            Assert.Equal("Algebra", retrieved.Title);
            Assert.Equal("Math", retrieved.Department.Name);
        }

        [Fact]
        public void CourseAssignment_HasCompositeKey()
        {
            using var context = TestDbContext.Create();
            var instructor = new Instructor
            {
                LastName = "Prof",
                FirstMidName = "A",
                HireDate = DateTime.Now,
                CourseAssignments = new List<CourseAssignment>()
            };
            context.Instructors.Add(instructor);

            var dept = new Department { Name = "CS", Budget = 10000, StartDate = DateTime.Now };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course { CourseID = 201, Title = "Programming", Credits = 4, DepartmentID = dept.DepartmentID };
            context.Courses.Add(course);
            context.SaveChanges();

            var assignment = new CourseAssignment { CourseID = 201, InstructorID = instructor.ID };
            context.CourseAssignments.Add(assignment);
            context.SaveChanges();

            var retrieved = context.CourseAssignments.First();
            Assert.Equal(201, retrieved.CourseID);
            Assert.Equal(instructor.ID, retrieved.InstructorID);
        }

        [Fact]
        public void Enrollment_LinksStudentAndCourse()
        {
            using var context = TestDbContext.Create();
            var student = new Student { LastName = "S", FirstMidName = "F", EnrollmentDate = DateTime.Now };
            context.Students.Add(student);

            var dept = new Department { Name = "D", Budget = 1000, StartDate = DateTime.Now };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course { CourseID = 301, Title = "History", Credits = 3, DepartmentID = dept.DepartmentID };
            context.Courses.Add(course);
            context.SaveChanges();

            var enrollment = new Enrollment { StudentID = student.ID, CourseID = 301, Grade = Grade.B };
            context.Enrollments.Add(enrollment);
            context.SaveChanges();

            var retrieved = context.Enrollments
                .Include(e => e.Student)
                .Include(e => e.Course)
                .First();
            Assert.Equal("S", retrieved.Student.LastName);
            Assert.Equal("History", retrieved.Course.Title);
            Assert.Equal(Grade.B, retrieved.Grade);
        }

        [Fact]
        public void OfficeAssignment_OneToOneWithInstructor()
        {
            using var context = TestDbContext.Create();
            var instructor = new Instructor
            {
                LastName = "Office",
                FirstMidName = "Prof",
                HireDate = DateTime.Now,
                CourseAssignments = new List<CourseAssignment>()
            };
            context.Instructors.Add(instructor);
            context.SaveChanges();

            var office = new OfficeAssignment { InstructorID = instructor.ID, Location = "Room 101" };
            context.OfficeAssignments.Add(office);
            context.SaveChanges();

            var retrieved = context.Instructors
                .Include(i => i.OfficeAssignment)
                .First(i => i.ID == instructor.ID);
            Assert.NotNull(retrieved.OfficeAssignment);
            Assert.Equal("Room 101", retrieved.OfficeAssignment.Location);
        }

        [Fact]
        public void Person_FullName_ReturnsLastCommaFirst()
        {
            using var context = TestDbContext.Create();
            var student = new Student
            {
                LastName = "Smith",
                FirstMidName = "John",
                EnrollmentDate = DateTime.Now
            };
            context.Students.Add(student);
            context.SaveChanges();

            var retrieved = context.Students.First();
            Assert.Equal("Smith, John", retrieved.FullName);
        }

        [Fact]
        public void Department_WithAdministrator_LoadsRelationship()
        {
            using var context = TestDbContext.Create();
            var instructor = new Instructor
            {
                LastName = "Admin",
                FirstMidName = "Boss",
                HireDate = DateTime.Now,
                CourseAssignments = new List<CourseAssignment>()
            };
            context.Instructors.Add(instructor);
            context.SaveChanges();

            var dept = new Department
            {
                Name = "Managed",
                Budget = 75000,
                StartDate = DateTime.Now,
                InstructorID = instructor.ID
            };
            context.Departments.Add(dept);
            context.SaveChanges();

            var retrieved = context.Departments
                .Include(d => d.Administrator)
                .First(d => d.DepartmentID == dept.DepartmentID);
            Assert.NotNull(retrieved.Administrator);
            Assert.Equal("Admin", retrieved.Administrator.LastName);
        }
    }
}

