using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class DbInitializerTests
    {
        [Fact]
        public void Initialize_EmptyDatabase_SeedsAllData()
        {
            using var context = TestDbContext.Create();

            DbInitializer.Initialize(context);

            Assert.Equal(8, context.Students.Count());
            Assert.Equal(5, context.Instructors.Count());
            Assert.Equal(4, context.Departments.Count());
            Assert.Equal(7, context.Courses.Count());
            Assert.Equal(3, context.OfficeAssignments.Count());
            Assert.True(context.Enrollments.Count() >= 11);
            Assert.True(context.CourseAssignments.Count() >= 8);
        }

        [Fact]
        public void Initialize_AlreadySeeded_DoesNotDuplicate()
        {
            using var context = TestDbContext.Create();

            DbInitializer.Initialize(context);
            var firstCount = context.Students.Count();

            DbInitializer.Initialize(context);
            var secondCount = context.Students.Count();

            Assert.Equal(firstCount, secondCount);
        }

        [Fact]
        public void Initialize_SetsCorrectRelationships()
        {
            using var context = TestDbContext.Create();

            DbInitializer.Initialize(context);

            // Verify department has instructor admin
            var englishDept = context.Departments.First(d => d.Name == "English");
            Assert.NotNull(englishDept.InstructorID);

            // Verify enrollments link students to courses
            var alexanderEnrollments = context.Enrollments
                .Where(e => e.Student.LastName == "Alexander")
                .ToList();
            Assert.Equal(3, alexanderEnrollments.Count);
        }
    }
}

