        }

        [Fact]
        public void Edit_Post_WithValidImage_UpdatesImagePath()
        {
            var course = CreateCourse(700, "ImageCourse");
            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("new_image.jpg");
            fileMock.Setup(f => f.Length).Returns(2048);
            fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            var result = _controller.Edit(course, fileMock.Object) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
        }

        [Fact]
        public void Edit_Post_WithInvalidExtension_ReturnsModelError()
        {
            var course = CreateCourse(701, "BadFile");
            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("hack.exe");
            fileMock.Setup(f => f.Length).Returns(1024);

            var result = _controller.Edit(course, fileMock.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Edit_Post_WithOversizedFile_ReturnsModelError()
        {
            var course = CreateCourse(702, "BigFile");
            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("big.png");
            fileMock.Setup(f => f.Length).Returns(6 * 1024 * 1024);

            var result = _controller.Edit(course, fileMock.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Edit_Post_InvalidModel_ReturnsView()
        {
            _controller.ModelState.AddModelError("Title", "Required");
            var course = new Course { CourseID = 800, Credits = 3 };

            var result = _controller.Edit(course, null) as ViewResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void DeleteConfirmed_WithImagePath_AttemptsFileDeletion()
        {
            var dept = CreateDepartment();
            var course = new Course
            {
                CourseID = 900,
                Title = "WithImage",
                Credits = 3,
                DepartmentID = dept.DepartmentID,
                TeachingMaterialImagePath = "/Uploads/TeachingMaterials/nonexistent.jpg"
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var result = _controller.DeleteConfirmed(900) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Null(_context.Courses.Find(900));
        }
    }
}

