using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class ModelTests
    {
        [Fact]
        public void ErrorViewModel_Properties_WorkCorrectly()
        {
            var model = new ErrorViewModel { RequestId = "abc123" };

            Assert.Equal("abc123", model.RequestId);
            Assert.True(model.ShowRequestId);

            model.RequestId = null;
            Assert.False(model.ShowRequestId);
        }

        [Fact]
        public void Notification_AllProperties_CanBeSetAndRead()
        {
            var now = DateTime.Now;
            var notification = new Notification
            {
                Id = 1,
                EntityType = "Student",
                EntityId = "42",
                Operation = "CREATE",
                Message = "Test message",
                CreatedAt = now,
                CreatedBy = "Admin",
                IsRead = true,
                ReadAt = now
            };

            Assert.Equal(1, notification.Id);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("42", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("Test message", notification.Message);
            Assert.Equal(now, notification.CreatedAt);
            Assert.Equal("Admin", notification.CreatedBy);
            Assert.True(notification.IsRead);
            Assert.Equal(now, notification.ReadAt);
        }

        [Fact]
        public void Course_Properties_WorkCorrectly()
        {
            var course = new Course
            {
                CourseID = 101,
                Title = "Test",
                Credits = 3,
                DepartmentID = 1,
                TeachingMaterialImagePath = "/path/img.jpg",
                Department = new Department { Name = "Dept" },
                Enrollments = new List<Enrollment>(),
                CourseAssignments = new List<CourseAssignment>()
            };

            Assert.Equal(101, course.CourseID);
            Assert.Equal("Test", course.Title);
            Assert.Equal(3, course.Credits);
            Assert.Equal(1, course.DepartmentID);
            Assert.Equal("/path/img.jpg", course.TeachingMaterialImagePath);
            Assert.NotNull(course.Department);
            Assert.Empty(course.Enrollments);
            Assert.Empty(course.CourseAssignments);
        }

        [Fact]
        public void Department_Properties_WorkCorrectly()
        {
            var dept = new Department
            {
                DepartmentID = 5,
                Name = "CS",
                Budget = 250000m,
                StartDate = new DateTime(2020, 1, 1),
                InstructorID = 10,
                RowVersion = new byte[] { 1, 2, 3 },
                Administrator = new Instructor { LastName = "Boss", FirstMidName = "The", HireDate = DateTime.Now },
                Courses = new List<Course>()
            };

            Assert.Equal(5, dept.DepartmentID);
            Assert.Equal("CS", dept.Name);
            Assert.Equal(250000m, dept.Budget);
            Assert.Equal(10, dept.InstructorID);
            Assert.NotNull(dept.RowVersion);
            Assert.NotNull(dept.Administrator);
            Assert.Empty(dept.Courses);
        }

        [Fact]
        public void CourseAssignment_Properties_WorkCorrectly()
        {
            var ca = new CourseAssignment
            {
                InstructorID = 1,
                CourseID = 2,
                Instructor = new Instructor { LastName = "A", FirstMidName = "B", HireDate = DateTime.Now },
                Course = new Course { CourseID = 2, Title = "C", Credits = 3 }
            };

            Assert.Equal(1, ca.InstructorID);
            Assert.Equal(2, ca.CourseID);
            Assert.NotNull(ca.Instructor);
            Assert.NotNull(ca.Course);
        }

        [Fact]
        public void OfficeAssignment_Properties_WorkCorrectly()
        {
            var oa = new OfficeAssignment
            {
                InstructorID = 7,
                Location = "Room 42",
                Instructor = new Instructor { LastName = "P", FirstMidName = "Q", HireDate = DateTime.Now }
            };

            Assert.Equal(7, oa.InstructorID);
            Assert.Equal("Room 42", oa.Location);
            Assert.NotNull(oa.Instructor);
        }

        [Fact]
        public void InstructorIndexData_Properties_WorkCorrectly()
        {
            var data = new InstructorIndexData
            {
                Instructors = new List<Instructor>(),
                Courses = new List<Course>(),
                Enrollments = new List<Enrollment>()
            };

            Assert.Empty(data.Instructors);
            Assert.Empty(data.Courses);
            Assert.Empty(data.Enrollments);
        }

        [Fact]
        public void Enrollment_Properties_WorkCorrectly()
        {
            var enrollment = new Enrollment
            {
                EnrollmentID = 1,
                CourseID = 100,
                StudentID = 5,
                Grade = Grade.A,
                Course = new Course { CourseID = 100, Title = "X", Credits = 3 },
                Student = new Student { LastName = "Y", FirstMidName = "Z", EnrollmentDate = DateTime.Now }
            };

            Assert.Equal(1, enrollment.EnrollmentID);
            Assert.Equal(100, enrollment.CourseID);
            Assert.Equal(5, enrollment.StudentID);
            Assert.Equal(Grade.A, enrollment.Grade);
            Assert.NotNull(enrollment.Course);
            Assert.NotNull(enrollment.Student);
        }

        [Fact]
        public void Enrollment_NullGrade_IsValid()
        {
            var enrollment = new Enrollment { EnrollmentID = 2, CourseID = 1, StudentID = 1 };

            Assert.Null(enrollment.Grade);
        }

        [Fact]
        public void AssignedCourseData_Properties_WorkCorrectly()
        {
            var data = new AssignedCourseData
            {
                CourseID = 101,
                Title = "Test Course",
                Assigned = true
            };

            Assert.Equal(101, data.CourseID);
            Assert.Equal("Test Course", data.Title);
            Assert.True(data.Assigned);
        }

        [Fact]
        public void Student_Enrollments_CanBeSet()
        {
            var student = new Student
            {
                LastName = "Test",
                FirstMidName = "Student",
                EnrollmentDate = new DateTime(2023, 9, 1),
                Enrollments = new List<Enrollment> { new Enrollment { CourseID = 1 } }
            };

            Assert.Single(student.Enrollments);
        }

        [Fact]
        public void Instructor_Properties_WorkCorrectly()
        {
            var instructor = new Instructor
            {
                LastName = "Smith",
                FirstMidName = "John",
                HireDate = new DateTime(2020, 5, 15),
                CourseAssignments = new List<CourseAssignment>(),
                OfficeAssignment = new OfficeAssignment { Location = "Room 1" }
            };

            Assert.Equal("Smith", instructor.LastName);
            Assert.Equal("John", instructor.FirstMidName);
            Assert.Equal(new DateTime(2020, 5, 15), instructor.HireDate);
            Assert.Empty(instructor.CourseAssignments);
            Assert.NotNull(instructor.OfficeAssignment);
            Assert.Equal("Smith, John", instructor.FullName);
        }
    }
}

